function deepClone(x){return JSON.parse(JSON.stringify(x));}
let stored=null;try{stored=JSON.parse(localStorage.getItem(KEY)||'null')}catch(e){stored=null}
let data=stored||deepClone(DEFAULT_DATA);
function migrate(){
 if(!Array.isArray(data.users))data.users=[];
 let admin=data.users.find(u=>u.admin);if(!admin){admin={id:'admin',username:'directionadmin',email:ADMIN_EMAIL,password:ADMIN_PASSWORD,admin:true,joined:'2010'};data.users.unshift(admin)}
 data.users.forEach(u=>{u.stats=u.stats||{};if(typeof u.stats.gamesPlayed!=='number')u.stats.gamesPlayed=0;if(typeof u.stats.quizPlays!=='number')u.stats.quizPlays=0;});
 if(!data.site)data.site=deepClone(DEFAULT_DATA.site);else Object.assign(data.site,deepClone(DEFAULT_DATA.site),data.site);
 if(!data.fun)data.fun=deepClone(DEFAULTS);else {data.fun.randomBits=data.fun.randomBits||deepClone(DEFAULTS.randomBits);data.fun.jokes=data.fun.jokes||deepClone(DEFAULTS.jokes);data.fun.challenges=data.fun.challenges||deepClone(DEFAULTS.challenges);data.fun.thisOrThat=data.fun.thisOrThat||deepClone(DEFAULTS.thisOrThat);data.fun.songGame=data.fun.songGame||deepClone(DEFAULTS.songGame)}
 if(!Array.isArray(data.submissions))data.submissions=[];data.submissions.forEach(s=>{s.likedBy=Array.isArray(s.likedBy)?s.likedBy:[];s.likes=s.likedBy.length;if(s.image==='assets/1d-plane.png')s.image='assets/one-direction-jump.jpg';if(s.image&&!s.credit)s.credit='Original creator/source credit supplied by uploader';});
 if(!Array.isArray(data.facts))data.facts=[];if(!Array.isArray(data.updates))data.updates=[];if(!Array.isArray(data.quizzes))data.quizzes=[];
 data.quizzes.forEach(q=>{q.status=q.status||'approved';q.plays=Number(q.plays)||0;q.questions=Array.isArray(q.questions)?q.questions:[];q.questions.forEach(qq=>{qq.choices=Array.isArray(qq.choices)?qq.choices:[];qq.answer=Math.max(0,Math.min(Number(qq.answer)||0,qq.choices.length-1));});});
 if(!data.poll)data.poll=deepClone(DEFAULT_DATA.poll);if(!data.poll.id)data.poll.id=uid('poll');if(!Array.isArray(data.poll.options))data.poll.options=[];if(!data.poll.votes)data.poll.votes={};
 // The old prototype used one global counter. Do not copy it into user stats: fresh per-user tracking is the accurate source.
 data.gamesPlayed=Object.values(data.users).reduce((sum,u)=>sum+(Number(u.stats?.gamesPlayed)||0),0);
 save();
}
function save(){localStorage.setItem(KEY,JSON.stringify(data))}
migrate();
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function uid(prefix='x'){return prefix+Date.now().toString(36)+Math.random().toString(36).slice(2,7)}
function current(){return data.users.find(u=>u.id===data.currentUser)}
function toast(x){const t=document.getElementById('toast');t.textContent=x;t.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>t.classList.remove('show'),2600)}
function incGame(){const u=current();if(u){u.stats=u.stats||{};u.stats.gamesPlayed=(u.stats.gamesPlayed||0)+1;}data.gamesPlayed=(data.gamesPlayed||0)+1;save();renderStats();renderCommunity();}
function likeButton(item){const u=current();const liked=u&&Array.isArray(item.likedBy)&&item.likedBy.includes(u.id);const count=Array.isArray(item.likedBy)?item.likedBy.length:(Number(item.likes)||0);return `<button class="like-btn ${liked?'liked':''}" data-like-id="${esc(item.id)}" aria-pressed="${liked}">♥ <span>${count}</span> ${liked?'LIKED':'LIKE'}</button>`}
function bindLikes(){document.querySelectorAll('.like-btn').forEach(btn=>btn.onclick=()=>{const u=current();if(!u){toast('Log in to like a message.');location.hash='login';return}const id=btn.dataset.likeId;const item=data.submissions.find(s=>s.id===id);if(!item)return;item.likedBy=Array.isArray(item.likedBy)?item.likedBy:[];const i=item.likedBy.indexOf(u.id);if(i>=0)item.likedBy.splice(i,1);else item.likedBy.push(u.id);item.likes=item.likedBy.length;save();renderWall();renderCommunity();toast(i>=0?'Like removed.':'Liked!');});}

function go(){const id=location.hash.slice(1)||'home';document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id===id));render();window.scrollTo(0,0);if(window.innerWidth<=850)document.getElementById('nav').style.display=''}
window.addEventListener('hashchange',go);
document.getElementById('menuBtn').onclick=()=>{const n=document.getElementById('nav');n.style.display=n.style.display==='flex'?'':'flex'};

function renderNav(){const a=document.getElementById('authNav'),u=current();a.innerHTML=u?`<a href="#community">@${esc(u.username)}</a>${u.admin?'<a href="#admin">CONTROL ROOM</a>':''}<a href="#" id="logout">LOG OUT</a>`:'<a href="#login">LOG IN</a><a href="#signup" class="join-link">JOIN</a>';const l=document.getElementById('logout');if(l)l.onclick=e=>{e.preventDefault();data.currentUser=null;save();toast('Logged out.');location.hash='home'}}

function mediaMarkup(s,cls='submission-media'){if(s.video)return `<video class="${cls}" controls preload="metadata" src="${s.video}"></video>`;if(s.image)return `<img class="${cls}" src="${s.image}" alt="Fan-submitted picture">`;return ''}
function submissionCard(s,withDelete=false){const long=(s.text||'').length>650;return `<article class="submission-card ${long?'long-post':''}">${mediaMarkup(s)}<div class="submission-body"><span class="tag">${esc(s.category)}</span><p class="post-text">${esc(s.text||'')}</p>${s.credit?`<div class="media-credit"><b>Credit:</b> ${esc(s.credit)}</div>`:''}<div class="post-meta"><div><div class="username">${esc(s.user)}</div><small>${esc(s.date||'')}</small></div>${likeButton(s)}</div>${withDelete?`<button class="small own-delete" data-id="${esc(s.id)}">DELETE MY POST</button>`:''}</div></article>`}
let wallFilter='all';
function renderWall(filter=wallFilter){wallFilter=filter;const list=data.submissions.filter(s=>s.status==='approved'&&(filter==='all'||s.category===filter));document.getElementById('wallSubmissions').innerHTML=list.length?list.map(submissionCard).join(''):'<div class="empty">Nothing here yet. Add yours!</div>';document.getElementById('homeSubmissions').innerHTML=list.slice(0,3).map(submissionCard).join('')||'<div class="empty">The wall is waiting for you.</div>';bindLikes()}
document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{document.querySelectorAll('.filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderWall(b.dataset.filter)});
document.getElementById('findMine').onclick=()=>{const u=current(),box=document.getElementById('wallMine');if(!u){box.innerHTML='<div class="notice">Log in or sign up first and we can show every message you have posted.</div>';return}const mine=data.submissions.filter(s=>s.user==='@'+u.username);box.innerHTML=`<div class="mine-box"><h2>YOUR MESSAGES</h2><p>${mine.length} submission(s) found. Like counts are shown; individual likers are never displayed.</p>${mine.length?mine.map(s=>submissionCard(s,true)).join(''):'<p>You have not posted anything yet.</p>'}</div>`;box.querySelectorAll('.own-delete').forEach(btn=>btn.onclick=()=>{const i=data.submissions.findIndex(s=>s.id===btn.dataset.id);if(i>=0&&data.submissions[i].user==='@'+u.username){data.submissions.splice(i,1);save();toast('Your post was deleted.');document.getElementById('findMine').click();renderWall()}});bindLikes()};

function renderFacts(){const list=data.facts.filter(f=>f.status==='approved');document.getElementById('factsList').innerHTML=list.map(f=>`<article class="fact-card"><span class="tag">${esc(f.category)}</span><h3>DID YOU KNOW?</h3><p>${esc(f.text)}</p><div class="fact-source"><b>Source:</b> ${esc(f.source)}<br><b>Submitted by:</b> ${esc(f.user)}</div></article>`).join('')||'<div class="empty">No facts yet.</div>'}

function renderSubmit(){const box=document.getElementById('submitArea'),u=current();if(!u){box.innerHTML='<div class="submit-box"><h2>JOIN FIRST</h2><p>Create an account so the site knows which username to attach to your contribution.</p><a class="btn red" href="#signup">SIGN UP</a> <a class="btn white" href="#login">LOG IN</a></div>';return}box.innerHTML=`<div class="submit-box"><form id="submissionForm"><label>Category<select id="category"><option>One Direction</option><option>Harry</option><option>Louis</option><option>Liam</option><option>Zayn</option><option>Niall</option></select></label><label>Your post<textarea id="message" maxlength="3000" placeholder="Memory, joke, story, fan message..."></textarea></label><label>Add one picture or video <input id="media" type="file" accept="image/png,image/jpeg,image/webp,image/gif,video/mp4,video/webm,video/ogg"></label><div id="preview"></div><div id="creditWrap" class="conditional-media"><label>Credits / source for your media<input id="credit" maxlength="500" placeholder="e.g. My own photo / @creator / source URL"></label><label class="check-label"><input id="rightsCheck" type="checkbox"> I have the right, permission or licence to share this content, and the credit above is accurate.</label></div><p class="privacy-note">Your public post shows your chosen username, not your email or real name. Credits are shown publicly when you upload media.</p><p class="media-note">Prototype limits: images up to 4 MB and videos up to 8 MB. The final public version should use cloud storage instead of browser storage.</p><button class="btn red">SEND TO THE FAN WALL →</button></form></div>`;const media=document.getElementById('media'),wrap=document.getElementById('creditWrap'),credit=document.getElementById('credit'),rights=document.getElementById('rightsCheck');function syncMedia(){const f=media.files[0];const has=!!f;wrap.style.display=has?'grid':'none';credit.required=has;rights.required=has}syncMedia();media.onchange=e=>{const f=e.target.files[0],p=document.getElementById('preview');syncMedia();if(!f){p.innerHTML='';return}const isVideo=f.type.startsWith('video/'),max=isVideo?8:4;if(f.size>max*1024*1024){toast(`Please choose a ${isVideo?'video':'image'} under ${max} MB in this prototype.`);e.target.value='';p.innerHTML='';syncMedia();return}const r=new FileReader();r.onload=()=>p.innerHTML=isVideo?`<video class="preview-media" controls src="${r.result}"></video>`:`<img src="${r.result}" alt="Preview" class="preview-media">`;r.readAsDataURL(f)};document.getElementById('submissionForm').onsubmit=submitPost}
function submitPost(e){e.preventDefault();const u=current(),f=document.getElementById('media').files[0],has=!!f,credit=document.getElementById('credit').value.trim();if(has&&!credit)return toast('Please add a credit/source for your media.');if(has&&!document.getElementById('rightsCheck').checked)return toast('Please confirm you have the right, permission or licence to share the media.');const finish=(media,kind)=>{data.submissions.unshift({id:uid('s'),user:'@'+u.username,category:document.getElementById('category').value,type:kind?`Text + ${kind}`:'Text',text:document.getElementById('message').value.trim(),image:kind==='Photo'?media:null,video:kind==='Video'?media:null,mediaType:kind?kind.toLowerCase():null,credit:has?credit:'',status:'pending',date:new Date().toISOString().slice(0,10),likedBy:[],likes:0});save();toast('Submitted! It is now waiting for admin approval.');location.hash='community'};if(f){const isVideo=f.type.startsWith('video/');const r=new FileReader();r.onload=()=>finish(r.result,isVideo?'Video':'Photo');r.readAsDataURL(f)}else finish(null,null)}

document.getElementById('factForm').onsubmit=e=>{e.preventDefault();const u=current();if(!u){toast('Log in first so we can attach your username.');location.hash='login';return}data.facts.unshift({id:uid('f'),user:'@'+u.username,category:document.getElementById('factCategory').value,text:document.getElementById('factText').value.trim(),source:document.getElementById('factSource').value.trim(),status:'pending',date:new Date().toISOString().slice(0,10)});save();toast('Fact sent to the admins!');e.target.reset();location.hash='community'};
document.getElementById('updateSubmitForm').onsubmit=e=>{e.preventDefault();const u=current();if(!u){toast('Log in first so we can attach your username.');location.hash='login';return}const title=document.getElementById('updateSubmitTitle').value.trim(),body=document.getElementById('updateSubmitBody').value.trim();data.updates.unshift({id:uid('u'),title,body,user:'@'+u.username,status:'pending',date:new Date().toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'})});save();toast('Update sent to the news desk!');e.target.reset();location.hash='community'};

document.getElementById('signupForm').onsubmit=e=>{e.preventDefault();const username=document.getElementById('signupUsername').value.trim().replace(/^@/,''),email=document.getElementById('signupEmail').value.trim().toLowerCase(),password=document.getElementById('signupPassword').value;if(data.users.some(u=>u.email===email||u.username.toLowerCase()===username.toLowerCase()))return toast('That username or email is already taken.');const u={id:uid('u'),username,email,password,admin:false,joined:new Date().getFullYear(),stats:{gamesPlayed:0,quizPlays:0}};data.users.push(u);data.currentUser=u.id;save();toast('Welcome to OUR DIRECTION!');location.hash='community'};
document.getElementById('loginForm').onsubmit=e=>{e.preventDefault();const email=document.getElementById('loginEmail').value.trim().toLowerCase(),password=document.getElementById('loginPassword').value,u=data.users.find(x=>x.email===email&&x.password===password);if(!u)return toast('Incorrect email or password.');if(u.suspended)return toast('This account is currently suspended.');data.currentUser=u.id;save();toast('Welcome back!');location.hash='community'};

function renderUpdates(){const list=data.updates.filter(u=>u.status==='approved');document.getElementById('updatesList').innerHTML=list.length?list.map(u=>`<article class="update"><small>${esc(u.date)}</small><h2>${esc(u.title)}</h2><p>${esc(u.body)}</p><small>Posted by ${esc(u.user||'@directionadmin')}</small></article>`).join(''):'<div class="empty">No public updates yet. The news desk is suspiciously quiet.</div>'}
function pollMarkup(target){const box=document.getElementById(target),p=data.poll,total=Object.values(p.votes||{}).reduce((a,b)=>a+Number(b||0),0);box.innerHTML=`<div class="poll-question">${esc(p.question)}</div><div class="poll-options">${p.options.map(o=>{const n=Number(p.votes[o]||0),pct=total?Math.round(n/total*100):0;return `<button class="poll-option" data-opt="${esc(o)}"><span>${esc(o)}</span><b>${pct}%</b><span class="bar"><i style="width:${pct}%"></i></span></button>`}).join('')}</div><small>${total} votes so far · individual votes are private</small>`;box.querySelectorAll('.poll-option').forEach(b=>b.onclick=()=>{const u=current();if(!u){toast('Log in to vote.');location.hash='login';return}const key='odPollVoted_'+p.id+'_'+u.id;if(localStorage.getItem(key))return toast('You already voted in this poll.');const opt=b.dataset.opt;p.votes[opt]=(p.votes[opt]||0)+1;localStorage.setItem(key,'1');save();pollMarkup(target);renderStats();toast('Vote counted!')})}
function renderPoll(){pollMarkup('pollArea')}
function renderHomePollFact(){pollMarkup('homePoll');const fs=data.facts.filter(x=>x.status==='approved');document.getElementById('homeFact').textContent=fs[Math.floor(Math.random()*fs.length)]?.text||'More facts coming soon.'}

let totIndex=0,songIndex=0,songClue=0;
function nextTot(){const qs=data.fun.thisOrThat||[];if(!qs.length)return;const q=qs[totIndex%qs.length];document.getElementById('totQuestion').textContent=`${q[0]} OR ${q[1]}?`;document.querySelectorAll('.choice').forEach((b,i)=>b.textContent=q[i]);}
function resetSong(){const games=data.fun.songGame||[];if(!games.length)return;songIndex=Math.floor(Math.random()*games.length);songClue=0;document.getElementById('songClue').textContent='Clue 1: '+games[songIndex].clues[0];document.getElementById('songResult').textContent='';document.getElementById('songGuess').value=''}
document.getElementById('newJoke').onclick=()=>document.getElementById('joke').textContent=(data.fun.jokes||[])[Math.floor(Math.random()*(data.fun.jokes||[]).length)]||'No joke loaded.';
document.getElementById('randomBtn').onclick=()=>{document.getElementById('randomResult').textContent=(data.fun.randomBits||[])[Math.floor(Math.random()*(data.fun.randomBits||[]).length)]||'The chaos cupboard is empty.';incGame()};
document.querySelectorAll('.choice').forEach(b=>b.onclick=()=>{const qs=data.fun.thisOrThat||[];const q=qs[totIndex%qs.length];document.getElementById('totResult').textContent=`You chose ${b.textContent}. The extremely scientific community result is: ${Math.floor(55+Math.random()*31)}% agree.`;incGame();totIndex++;nextTot()});
document.getElementById('songClueBtn').onclick=()=>{const games=data.fun.songGame||[];if(!games.length)return;songClue=Math.min(songClue+1,games[songIndex].clues.length-1);document.getElementById('songClue').textContent='Clue '+(songClue+1)+': '+games[songIndex].clues[songClue]};
document.getElementById('songGuessBtn').onclick=()=>{const games=data.fun.songGame||[];if(!games.length)return;const g=document.getElementById('songGuess').value.trim().toLowerCase(),a=games[songIndex].answer.toLowerCase();if(g===a){document.getElementById('songResult').textContent='CORRECT. You are annoyingly good at this. 🎯';incGame();setTimeout(resetSong,500)}else document.getElementById('songResult').textContent='Nope. Try again or use another clue.'};
document.getElementById('newChallenge').onclick=()=>{const arr=data.fun.challenges||[];document.getElementById('challengeText').textContent=arr[Math.floor(Math.random()*arr.length)]||'No challenge loaded.'};

function renderStats(){document.getElementById('statUsers').textContent=data.users.length;document.getElementById('statMessages').textContent=data.submissions.filter(x=>x.status==='approved').length;document.getElementById('statQuizzes').textContent=data.quizzes.filter(x=>x.status==='approved').length;document.getElementById('statGames').textContent=data.gamesPlayed||0}

let quizFilter='all';
function renderQuizList(diff=quizFilter){quizFilter=diff;const list=data.quizzes.filter(q=>q.status==='approved'&&(diff==='all'||q.difficulty===diff));document.getElementById('quizList').innerHTML=list.map(q=>`<article class="quiz-card"><span class="tag">${esc(q.difficulty)}</span><small>${esc(q.category)} · ${q.plays||0} plays · ${q.questions.length} questions</small><h2>${esc(q.title)}</h2><p>${esc(q.description||'')}</p><b>BY ${esc(q.creator)}</b><button class="btn red take-quiz" data-id="${esc(q.id)}">TAKE QUIZ →</button></article>`).join('')||'<div class="empty">No quizzes in that category yet.</div>';document.querySelectorAll('.take-quiz').forEach(b=>b.onclick=()=>runQuiz(b.dataset.id))}
document.querySelectorAll('.quiz-filter').forEach(b=>b.onclick=()=>{document.querySelectorAll('.quiz-filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderQuizList(b.dataset.diff)});
function runQuiz(id){const q=data.quizzes.find(x=>x.id===id);if(!q||!q.questions.length)return toast('This quiz has no questions yet.');const wrap=document.getElementById('quizRunner');wrap.innerHTML=`<div class="modal"><button class="close" id="closeQuiz">×</button><small>${esc(q.difficulty)} · ${esc(q.category)} · ${q.questions.length} questions</small><h2>${esc(q.title)}</h2><form id="quizForm">${q.questions.map((x,i)=>`<fieldset><legend>${i+1}. ${esc(x.q)}</legend>${x.choices.map((c,j)=>`<label class="quiz-choice"><input type="radio" name="q${i}" value="${j}" required>${esc(c)}</label>`).join('')}</fieldset>`).join('')}<button class="btn red">FINISH QUIZ</button></form><div id="quizScore"></div></div>`;wrap.classList.add('show');document.getElementById('closeQuiz').onclick=()=>wrap.classList.remove('show');document.getElementById('quizForm').onsubmit=e=>{e.preventDefault();let score=0;q.questions.forEach((x,i)=>{if(Number(new FormData(e.target).get('q'+i))===x.answer)score++});q.plays=(q.plays||0)+1;const u=current();if(u){u.stats=u.stats||{};u.stats.quizPlays=(u.stats.quizPlays||0)+1}incGame();const pct=Math.round(score/q.questions.length*100);const msg=pct===100?'CERTIFIED DIRECTIONER.':'Solid effort. The rabbit hole goes deeper.';document.getElementById('quizScore').innerHTML=`<div class="score-card"><strong>${score}/${q.questions.length}</strong><p>${pct}% — ${msg}</p>${q.questions.map((x,i)=>`<p><b>${i+1}.</b> Correct answer: ${esc(x.choices[x.answer])}. ${esc(x.explain||'')}</p>`).join('')}<button type="button" class="btn white" id="closeScore">BACK TO QUIZZES</button></div>`;document.getElementById('closeScore').onclick=()=>wrap.classList.remove('show');renderQuizList()}}

function renderQuizMaker(){const box=document.getElementById('quizMaker'),u=current();if(!u){box.innerHTML='<h2>WANT TO MAKE A QUIZ?</h2><p>Sign up first. Community quizzes go live immediately. Admins can still edit or delete them.</p><a class="btn red" href="#signup">JOIN TO CREATE</a>';return}box.innerHTML=`<h2>CREATE A QUIZ</h2><p>Build as many questions as you want, with as many multiple-choice options as you need. Quizzes go live immediately.</p><form id="quizMakerForm"><label>Title<input id="qTitle" maxlength="80" required placeholder="e.g. How Well Do You Know FOUR?"></label><label>Description<input id="qDesc" maxlength="180" placeholder="What is this quiz about?"></label><div class="editor-grid"><label>Category<select id="qCat"><option>Songs</option><option>Albums</option><option>Members</option><option>1D History</option><option>Performances</option><option>Music Videos</option><option>Trivia</option><option>Fandom</option><option>Hard/Expert</option></select></label><label>Difficulty<select id="qDiff"><option>Easy</option><option>Medium</option><option>Hard</option><option>Expert</option></select></label></div><div id="makerQuestions"></div><button type="button" class="small" id="addQuestion">+ ADD ANOTHER QUESTION</button><button type="submit" class="btn red">POST QUIZ NOW →</button></form>`;const qbox=document.getElementById('makerQuestions');function addQuestion(q={q:'',choices:['','','',''],answer:0,explain:''}){const idx=qbox.children.length;const el=document.createElement('div');el.className='question-builder';el.innerHTML=`<div class="builder-head"><h3>QUESTION ${idx+1}</h3><button type="button" class="small remove-question">REMOVE</button></div><label>Question<input class="qb-question" required value="${esc(q.q)}" placeholder="Write the question..."></label><div class="option-builder">${q.choices.map((c,j)=>`<label>Option ${j+1}<input class="qb-choice" value="${esc(c)}" required></label>`).join('')}</div><button type="button" class="small add-option">+ ADD OPTION</button><label>Correct option<select class="qb-answer">${q.choices.map((c,j)=>`<option value="${j}" ${j===q.answer?'selected':''}>Option ${j+1}</option>`).join('')}</select></label><label>Explanation<input class="qb-explain" maxlength="240" value="${esc(q.explain||'')}" placeholder="Optional explanation"></label>`;qbox.appendChild(el);el.querySelector('.remove-question').onclick=()=>{if(qbox.children.length<=1)return toast('Keep at least one question.');el.remove();renumberQuestionBuilders()};el.querySelector('.add-option').onclick=()=>{const options=el.querySelector('.option-builder');const n=options.children.length+1;if(n>12)return toast('Keep quizzes to 12 options per question in this prototype.');const lab=document.createElement('label');lab.innerHTML=`Option ${n}<input class="qb-choice" required>`;options.appendChild(lab);updateAnswerSelect(el)};el.querySelectorAll('.qb-choice').forEach(i=>i.addEventListener('input',()=>updateAnswerSelect(el)));updateAnswerSelect(el)}function updateAnswerSelect(el){const sel=el.querySelector('.qb-answer'),n=el.querySelectorAll('.qb-choice').length,old=Number(sel.value);sel.innerHTML=Array.from({length:n},(_,j)=>`<option value="${j}">Option ${j+1}</option>`).join('');sel.value=String(Math.min(old,n-1))}function renumberQuestionBuilders(){qbox.querySelectorAll('.question-builder').forEach((el,i)=>el.querySelector('h3').textContent=`QUESTION ${i+1}`)}addQuestion();document.getElementById('addQuestion').onclick=()=>addQuestion();document.getElementById('quizMakerForm').onsubmit=e=>{e.preventDefault();const questions=[...qbox.querySelectorAll('.question-builder')].map(el=>({q:el.querySelector('.qb-question').value.trim(),choices:[...el.querySelectorAll('.qb-choice')].map(x=>x.value.trim()).filter(Boolean),answer:Number(el.querySelector('.qb-answer').value),explain:el.querySelector('.qb-explain').value.trim()}));if(questions.some(q=>q.choices.length<2))return toast('Each question needs at least two options.');data.quizzes.unshift({id:uid('q'),title:document.getElementById('qTitle').value.trim(),description:document.getElementById('qDesc').value.trim(),category:document.getElementById('qCat').value,difficulty:document.getElementById('qDiff').value,plays:0,creator:'@'+u.username,status:'approved',questions});save();toast('Quiz posted! Admins can edit or delete it from the Control Room.');e.target.reset();location.hash='quizzes'}}

function renderCommunity(){const box=document.getElementById('communityArea'),u=current();if(!u){box.innerHTML='<div class="community-landing section"><article class="home-card"><h2>JOIN THE COMMUNITY</h2><p>Pick a username, build badges, make quizzes, post memories and become part of the chaos.</p><a class="btn red" href="#signup">SIGN UP</a> <a class="btn white" href="#login">LOG IN</a></article></div>';return}u.stats=u.stats||{gamesPlayed:0,quizPlays:0};const posts=data.submissions.filter(x=>x.user==='@'+u.username),quizzes=data.quizzes.filter(x=>x.creator==='@'+u.username),facts=data.facts.filter(x=>x.user==='@'+u.username),updates=data.updates.filter(x=>x.user==='@'+u.username),badges=[];if(posts.length>=1)badges.push('FIRST MESSAGE');if(posts.length>=5)badges.push('WALL REGULAR');if(quizzes.length>=1)badges.push('QUIZ CREATOR');if(u.stats.gamesPlayed>=5)badges.push('CHAOS PARTICIPANT');const pending=[...posts,...facts,...updates].filter(x=>x.status==='pending').length;box.innerHTML=`<div class="profile-layout section"><aside class="profile-card"><div class="avatar">${esc(u.username[0]?.toUpperCase()||'D')}</div><h2>@${esc(u.username)}</h2><p>Certified Directioner in training.</p><div class="badges">${badges.length?badges.map(b=>`<span>${esc(b)}</span>`).join(''):'<small>Your first badge is waiting for you.</small>'}</div><div class="profile-note">Likes on your posts are anonymous: you see the number, never the names.</div></aside><div class="profile-main"><div class="stats-cards"><div><b>${posts.length}</b><span>wall messages</span></div><div><b>${quizzes.length}</b><span>quizzes made</span></div><div><b>${u.stats.gamesPlayed}</b><span>games played</span></div><div><b>${u.stats.quizPlays}</b><span>quiz plays</span></div></div><div class="home-card"><small>ACTIVITY</small><h2>YOUR DIRECTIONER TRAIL</h2><p>Games played counts only completed games/quiz attempts. It is tracked separately for your account, so opening pages or changing tabs cannot inflate it.</p><p>Posts: ${posts.length} · Facts: ${facts.length} · Updates: ${updates.length} · Pending contributions: ${pending}</p></div><div class="home-card"><small>YOUR FAN WALL POSTS</small><div class="account-posts">${posts.length?posts.map(s=>submissionCard(s)).join(''):'<p>You have not posted to the Fan Wall yet.</p>'}</div></div></div></div>`;bindLikes()}

function adminButtons(kind,x){const base='<div class="admin-actions">';if(kind==='quiz')return base+`<button class="edit" onclick="adminEdit('${kind}','${x.id}')">EDIT</button><button class="delete" onclick="adminDelete('${kind}','${x.id}')">DELETE</button></div>`;let b='';if(x.status==='pending')b+=`<button class="approve" onclick="adminStatus('${kind}','${x.id}','approved')">APPROVE</button><button class="reject" onclick="adminStatus('${kind}','${x.id}','rejected')">REJECT</button>`;if(x.status==='rejected')b+=`<button class="approve" onclick="adminStatus('${kind}','${x.id}','approved')">APPROVE</button>`;b+=`<button class="edit" onclick="adminEdit('${kind}','${x.id}')">EDIT</button><button class="delete" onclick="adminDelete('${kind}','${x.id}')">DELETE</button>`;return base+b+'</div>'}
function collectionFor(kind){return kind==='submission'?'submissions':kind==='fact'?'facts':kind==='update'?'updates':'quizzes'}
function adminStatus(kind,id,status){if(!current()?.admin)return;const x=data[collectionFor(kind)].find(v=>v.id===id);if(!x)return;x.status=status;save();toast(status==='approved'?'Approved.':'Rejected.');render();renderAdmin()}
function adminDelete(kind,id){if(!current()?.admin)return;const arr=data[collectionFor(kind)],i=arr.findIndex(v=>v.id===id);if(i<0)return;if(!confirm('Delete this content permanently from this prototype?'))return;arr.splice(i,1);save();toast('Deleted.');render();renderAdmin()}
function adminEdit(kind,id){if(!current()?.admin)return; if(kind==='quiz'){showQuizEditor(id);return}const arr=data[collectionFor(kind)],x=arr.find(v=>v.id===id);if(!x)return;if(kind==='submission'){x.category=prompt('Category:',x.category)||x.category;x.text=prompt('Post text:',x.text||'')??x.text;x.credit=prompt('Credits / source:',x.credit||'')??x.credit}else if(kind==='fact'){x.category=prompt('Category:',x.category)||x.category;x.text=prompt('Fact:',x.text)||x.text;x.source=prompt('Source:',x.source)||x.source}else if(kind==='update'){x.title=prompt('Update title:',x.title)||x.title;x.body=prompt('Update body:',x.body)||x.body}save();toast('Edited and saved.');render();renderAdmin()}

function showQuizEditor(id){const q=data.quizzes.find(x=>x.id===id);if(!q)return;const el=document.getElementById('adminSection');document.querySelectorAll('.admin-tab').forEach(x=>x.classList.remove('active'));el.innerHTML=`<div class="editor"><div class="builder-head"><div><small>QUIZ EDITOR</small><h2>${esc(q.title)}</h2></div><button class="small" id="backAdmin">← BACK</button></div><form id="quizEditForm"><label>Title<input id="eqTitle" value="${esc(q.title)}" required></label><label>Description<input id="eqDesc" value="${esc(q.description||'')}"></label><div class="editor-grid"><label>Category<input id="eqCat" value="${esc(q.category||'Trivia')}"></label><label>Difficulty<select id="eqDiff">${['Easy','Medium','Hard','Expert'].map(d=>`<option ${q.difficulty===d?'selected':''}>${d}</option>`).join('')}</select></label></div><div id="editQuestions"></div><button type="button" class="small" id="addEditQuestion">+ ADD QUESTION</button><button class="btn red">SAVE QUIZ</button></form></div>`;const qb=document.getElementById('editQuestions');function addQ(qx={q:'',choices:['',''],answer:0,explain:''}){const el=document.createElement('div');el.className='question-builder';el.innerHTML=`<div class="builder-head"><h3>QUESTION</h3><button type="button" class="small remove-question">REMOVE</button></div><label>Question<input class="qb-question" value="${esc(qx.q)}" required></label><div class="option-builder">${qx.choices.map(c=>`<label>Option<input class="qb-choice" value="${esc(c)}" required></label>`).join('')}</div><button type="button" class="small add-option">+ ADD OPTION</button><label>Correct option<select class="qb-answer">${qx.choices.map((c,i)=>`<option value="${i}" ${i===qx.answer?'selected':''}>Option ${i+1}</option>`).join('')}</select></label><label>Explanation<input class="qb-explain" value="${esc(qx.explain||'')}"></label>`;qb.appendChild(el);el.querySelector('.remove-question').onclick=()=>{if(qb.children.length<=1)return toast('Keep at least one question.');el.remove();renumber()};el.querySelector('.add-option').onclick=()=>{if(el.querySelectorAll('.qb-choice').length>=12)return toast('Keep quizzes to 12 options per question in this prototype.');const n=el.querySelectorAll('.qb-choice').length+1,lab=document.createElement('label');lab.innerHTML=`Option<input class="qb-choice" required>`;el.querySelector('.option-builder').appendChild(lab);updateSelect(el)};updateSelect(el)}function updateSelect(el){const sel=el.querySelector('.qb-answer'),old=Number(sel.value),n=el.querySelectorAll('.qb-choice').length;sel.innerHTML=Array.from({length:n},(_,i)=>`<option value="${i}">Option ${i+1}</option>`).join('');sel.value=String(Math.min(old,n-1))}function renumber(){qb.querySelectorAll('.question-builder').forEach((x,i)=>x.querySelector('h3').textContent=`QUESTION ${i+1}`)}(q.questions.length?q.questions:[{q:'',choices:['',''],answer:0,explain:''}]).forEach(addQ);renumber();document.getElementById('addEditQuestion').onclick=()=>{addQ();renumber()};document.getElementById('backAdmin').onclick=()=>showAdminSection('all',null);document.getElementById('quizEditForm').onsubmit=e=>{e.preventDefault();const questions=[...qb.querySelectorAll('.question-builder')].map(el=>({q:el.querySelector('.qb-question').value.trim(),choices:[...el.querySelectorAll('.qb-choice')].map(x=>x.value.trim()).filter(Boolean),answer:Number(el.querySelector('.qb-answer').value),explain:el.querySelector('.qb-explain').value.trim()}));if(questions.some(x=>x.choices.length<2))return toast('Each question needs at least two options.');Object.assign(q,{title:document.getElementById('eqTitle').value.trim(),description:document.getElementById('eqDesc').value.trim(),category:document.getElementById('eqCat').value.trim(),difficulty:document.getElementById('eqDiff').value,questions});save();toast('Quiz updated!');showAdminSection('all',null);renderQuizList();renderAdmin()}}

function renderAdmin(){const box=document.getElementById('adminArea'),u=current();if(!u?.admin){box.innerHTML='<div class="empty">This area is private.</div>';return}const ps=data.submissions.filter(x=>x.status==='pending'),pf=data.facts.filter(x=>x.status==='pending'),pu=data.updates.filter(x=>x.status==='pending');box.innerHTML=`<div class="admin-box"><div class="notice"><b>ADMIN TIP:</b> Quizzes publish immediately. You can still edit/delete them. Wall posts, facts and updates use moderation. The editor below controls the site copy and Fun Page content.</div><div class="admin-top"><div class="stat"><small>PENDING POSTS</small><strong>${ps.length}</strong></div><div class="stat"><small>PENDING FACTS</small><strong>${pf.length}</strong></div><div class="stat"><small>PENDING UPDATES</small><strong>${pu.length}</strong></div><div class="stat"><small>LIVE QUIZZES</small><strong>${data.quizzes.filter(x=>x.status==='approved').length}</strong></div><div class="stat"><small>USERS</small><strong>${data.users.length}</strong></div><div class="stat"><small>WALL LIKES</small><strong>${data.submissions.reduce((n,s)=>n+(s.likedBy?.length||0),0)}</strong></div></div><div class="admin-tabs"><button class="admin-tab active" onclick="showAdminSection('queue',this)">MODERATION QUEUE</button><button class="admin-tab" onclick="showAdminSection('all',this)">ALL CONTENT</button><button class="admin-tab" onclick="showAdminSection('users',this)">USERS</button><button class="admin-tab" onclick="showAdminSection('editor',this)">SITE + FUN EDITOR</button><button class="admin-tab" onclick="showAdminSection('poll',this)">DAILY POLL</button></div><div id="adminSection"></div></div>`;showAdminSection('queue',document.querySelector('.admin-tab.active'))}

function showAdminSection(section,btn){document.querySelectorAll('.admin-tab').forEach(x=>x.classList.remove('active'));if(btn)btn.classList.add('active');const el=document.getElementById('adminSection');if(!el)return;
 if(section==='editor'){el.innerHTML=`<div class="editor"><h2>SITE + FUN PAGE EDITOR</h2><p>Change the main site wording, homepage text, Fun Page games, jokes, challenges and Guess It bank without editing HTML.</p><form id="siteForm"><h3>MAIN SITE TEXT</h3><div class="editor-grid"><label>Homepage slogan<input id="editSlogan" value="${esc(data.site.slogan)}"></label><label>Homepage intro<input id="editCopy" value="${esc(data.site.copy)}"></label><label class="wide">Featured quote / pun<input id="editQuote" value="${esc(data.site.quote)}"></label><label>Fan Wall intro<input id="editWall" value="${esc(data.site.wallIntro)}"></label><label>Fun Page intro<input id="editFun" value="${esc(data.site.funIntro)}"></label><label>Quiz intro<input id="editQuiz" value="${esc(data.site.quizIntro)}"></label><label>Facts intro<input id="editFacts" value="${esc(data.site.factsIntro)}"></label><label>Updates intro<input id="editUpdates" value="${esc(data.site.updatesIntro)}"></label><label>Community intro<input id="editCommunity" value="${esc(data.site.communityIntro)}"></label><label>Submit intro<input id="editSubmit" value="${esc(data.site.submitIntro)}"></label><label>Rules intro<input id="editRules" value="${esc(data.site.rulesIntro)}"></label></div><h3>FUN PAGE CONTENT</h3><label>Jokes — one per line<textarea id="funJokes">${esc(data.fun.jokes.join('\n'))}</textarea></label><label>Random button results — one per line<textarea id="funRandom">${esc(data.fun.randomBits.join('\n'))}</textarea></label><label>Challenges — one per line<textarea id="funChallenges">${esc(data.fun.challenges.join('\n'))}</textarea></label><label>This or That — one pair per line, use <b>OPTION A | OPTION B</b><textarea id="funTOT">${esc(data.fun.thisOrThat.map(x=>x.join(' | ')).join('\n'))}</textarea></label><label>Guess It — one game per line, use <b>ANSWER | CLUE 1 | CLUE 2 | CLUE 3</b><textarea id="funSongs">${esc(data.fun.songGame.map(x=>[x.answer,...x.clues].join(' | ')).join('\n'))}</textarea></label><h3>FOOTER</h3><div class="editor-grid"><label>Footer line 1<input id="footer1" value="${esc(data.site.footer1)}"></label><label>Footer line 2<input id="footer2" value="${esc(data.site.footer2)}"></label><label>Footer copyright link text<input id="footer3" value="${esc(data.site.footer3)}"></label></div><button class="btn red">SAVE EVERYTHING</button></form></div>`;document.getElementById('siteForm').onsubmit=e=>{e.preventDefault();Object.assign(data.site,{slogan:editSlogan.value,copy:editCopy.value,quote:editQuote.value,wallIntro:editWall.value,funIntro:editFun.value,quizIntro:editQuiz.value,factsIntro:editFacts.value,updatesIntro:editUpdates.value,communityIntro:editCommunity.value,submitIntro:editSubmit.value,rulesIntro:editRules.value,footer1:footer1.value,footer2:footer2.value,footer3:footer3.value});data.fun.jokes=funJokes.value.split(/\n/).map(x=>x.trim()).filter(Boolean);data.fun.randomBits=funRandom.value.split(/\n/).map(x=>x.trim()).filter(Boolean);data.fun.challenges=funChallenges.value.split(/\n/).map(x=>x.trim()).filter(Boolean);data.fun.thisOrThat=funTOT.value.split(/\n/).map(x=>x.split('|').map(y=>y.trim()).filter(Boolean)).filter(x=>x.length>=2).map(x=>[x[0],x[1]]);data.fun.songGame=funSongs.value.split(/\n/).map(line=>line.split('|').map(x=>x.trim()).filter(Boolean)).filter(x=>x.length>=2).map(x=>({answer:x[0],clues:x.slice(1)}));save();toast('Site + Fun Page saved!');render();renderAdmin()};return}
 if(section==='users'){el.innerHTML=data.users.map(u=>`<div class="admin-item"><b>@${esc(u.username)}</b> ${u.admin?'· ADMIN':''} ${u.suspended?'· SUSPENDED':''}${!u.admin?`<div class="admin-actions"><button class="reject" onclick="toggleSuspend('${u.id}')">${u.suspended?'UNSUSPEND':'SUSPEND'}</button></div>`:''}</div>`).join('');return}
 if(section==='poll'){el.innerHTML=`<div class="editor"><h2>MANAGE DAILY POLL</h2><p>Change the question and use as many choices as you want. Saving a new poll starts its vote count from zero.</p><form id="pollForm"><label>Question<input id="pollQ" value="${esc(data.poll.question)}" required></label><label>Options — one per line<textarea id="pollO" required>${esc(data.poll.options.join('\n'))}</textarea></label><button class="btn red">SAVE DAILY POLL</button></form></div>`;document.getElementById('pollForm').onsubmit=e=>{e.preventDefault();const opts=pollO.value.split(/\n/).map(x=>x.trim()).filter(Boolean);if(opts.length<2)return toast('A poll needs at least two options.');data.poll={id:uid('poll'),question:pollQ.value.trim(),options:opts,votes:{}};save();toast('Daily poll updated!');render();renderAdmin()};return}
 let items=[];if(section==='queue')items=[...data.submissions.filter(x=>x.status==='pending').map(x=>({kind:'submission',...x})),...data.facts.filter(x=>x.status==='pending').map(x=>({kind:'fact',...x})),...data.updates.filter(x=>x.status==='pending').map(x=>({kind:'update',...x}))];else items=[...data.submissions.map(x=>({kind:'submission',...x})),...data.facts.map(x=>({kind:'fact',...x})),...data.updates.map(x=>({kind:'update',...x})),...data.quizzes.map(x=>({kind:'quiz',...x}))];el.innerHTML=items.length?items.map(x=>`<div class="admin-item"><span class="status ${x.status}">${esc(x.status)}</span> <b>${x.kind==='fact'?'FACT':x.kind==='update'?'UPDATE':x.kind==='quiz'?'QUIZ':'WALL POST'}</b> · ${esc(x.user||x.creator||'@directionadmin')} · ${esc(x.category||x.difficulty||'Site news')}<p>${esc(x.kind==='update'?x.title+': '+x.body:x.kind==='quiz'?x.title+': '+x.description:(x.text||''))}</p>${x.kind==='quiz'?`<p><b>${x.questions.length} questions · ${x.questions.reduce((n,q)=>n+q.choices.length,0)} total options</b></p>`:''}${x.source?`<p><b>Source:</b> ${esc(x.source)}</p>`:''}${x.credit?`<p><b>Credit:</b> ${esc(x.credit)}</p>`:''}${x.image?`<img src="${x.image}" class="admin-img" alt="Submitted image">`:''}${x.video?`<video src="${x.video}" class="admin-media" controls></video>`:''}${adminButtons(x.kind,x)}</div>`).join(''):'<p>Nothing to moderate right now. The queue is suspiciously peaceful.</p>'}
function toggleSuspend(id){if(!current()?.admin)return;const u=data.users.find(x=>x.id===id);if(u&&!u.admin){u.suspended=!u.suspended;save();toast(u.suspended?'User suspended.':'User unsuspended.');renderAdmin()}}

function render(){renderNav();document.getElementById('heroSlogan').textContent=data.site.slogan;document.getElementById('heroCopy').textContent=data.site.copy;document.getElementById('featuredQuote').textContent=data.site.quote;document.getElementById('joke').textContent=(data.fun.jokes||[])[Math.floor(Math.random()*(data.fun.jokes||[]).length)]||'Loading extremely important research...';document.querySelector('#wall .page-head p').textContent=data.site.wallIntro;document.querySelector('#fun .page-head p').textContent=data.site.funIntro;document.querySelector('#quizzes .page-head p').textContent=data.site.quizIntro;document.querySelector('#facts .page-head p').textContent=data.site.factsIntro;document.querySelector('#updates .page-head p').textContent=data.site.updatesIntro;document.querySelector('#community .page-head p').textContent=data.site.communityIntro;document.querySelector('#submit .page-head p').textContent=data.site.submitIntro;document.querySelector('#rules .page-head p').textContent=data.site.rulesIntro;document.querySelector('footer span:nth-child(1)').textContent=data.site.footer1;document.querySelector('footer span:nth-child(2)').textContent=data.site.footer2;document.querySelector('footer span:nth-child(3) a:first-child').textContent=data.site.footer3;renderWall();renderFacts();renderSubmit();renderAccount();renderUpdates();renderPoll();renderHomePollFact();renderStats();renderQuizList();renderQuizMaker();renderCommunity();renderAdmin();nextTot();if(!document.getElementById('songGuess').value&&!document.getElementById('songResult').textContent)resetSong()}
